<?php
// Original tracking design with the real order, its status history and the cancel / repeat-order decisions.
use App\Services\Workspace;
use App\UI\LiveForm as F;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->order($_GET['order'] ?? null));
if (isset($live['error']) || isset($live['error_code'])): ?><?= U::heading('Order not found', 'Choose an order from your order history.') ?><?= U::btn('My orders', '/customer/orders', 'primary', 'arrow-left') ?><?php return; endif;
$order = $live['order']; $station = $live['station']; $pickup = $order['fulfillment'] === 'pickup';
$steps = $pickup ? ['confirmed', 'preparing', 'ready', 'collected'] : ['confirmed', 'preparing', 'ready', 'out_for_delivery', 'delivered', 'completed'];
$copy = ['confirmed' => $pickup ? 'The station received your pickup order.' : 'Your order has been received.', 'preparing' => $pickup ? 'Your containers are being prepared.' : 'We’re getting your order ready.',
    'ready' => $pickup ? 'Collect your water at the station during opening hours.' : 'Your order is ready for delivery.', 'out_for_delivery' => 'Your order is on the way to your address.',
    'delivered' => 'Your order was delivered.', 'collected' => 'You collected your order at the station.', 'completed' => 'Order fully completed.'];
$reached = array_column($live['timeline'], 'at', 'to');
$stage = array_search($order['status'], $steps, true); $stage = $stage === false ? -1 : $stage;
$fee = $order['final_fee_centavos'] ?? $order['quoted_fee_centavos'];
$fields = ['order_id' => $order['id'], 'expected_version' => $order['version']];
?>
<div data-poll-url="/customer/tracking/status?order=<?= U::e($order['id']) ?>" data-poll-version="<?= (int) $order['version'] ?>" data-poll-seconds="30" hidden></div>
<?= U::heading('Order ' . $order['order_no'], $pickup ? 'Track your pickup and collection details.' : 'Track your order and delivery details.', U::btn('Message station', '/customer/messages?station=' . $station['id'], 'primary', 'message') . U::btn('My orders', '/customer/orders', 'secondary', 'arrow-left')) ?>
<div class="grid gap-5 lg:grid-cols-2"><div class="space-y-5"><section class="panel p-5 flex items-center gap-4"><?= U::productImage('h-24 w-24 rounded-lg bg-foam') ?><div><h2 class="font-bold text-xl"><?= U::e($station['name']) ?></h2><p class="muted">Brgy. <?= U::e($station['barangay'] ?: 'Hamtic') ?>, Hamtic, Antique</p><div class="mt-3"><?= S::badge($order['status'], $order['fulfillment']) ?></div></div></section><section class="panel p-5 md:p-6"><?= U::title('Order progress','orders','') ?><p class="muted mb-5"><?= U::e(S::label($order['status'], $order['fulfillment'])) ?>. Placed <?= U::e(S::time($order['created_at'], 'M j, Y · g:i A')) ?><?= $order['schedule_mode'] === 'scheduled' ? ', for ' . U::e(S::time($order['requested_at'], 'M j · g:i A')) : '' ?>. This page updates every 30 seconds.</p><ol><?php foreach ($steps as $i => $step): ?><li class="relative flex gap-4 pb-6 last:pb-0"><div class="relative flex flex-col items-center"><span class="relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full <?= $i <= $stage ? 'bg-water text-white' : 'bg-white border-2 border-line' ?>"><?= $i < $stage ? U::icon('check', 'size-5') : ($i === $stage ? U::icon($pickup || $stage >= 4 ? 'check' : 'truck', 'size-4') : '') ?></span><?php if ($i < count($steps) - 1): ?><span class="absolute top-8 bottom-0 w-0.5 <?= $i < $stage ? 'bg-water' : 'bg-line' ?>"></span><?php endif; ?></div><div class="flex-1"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-bold"><?= U::e(S::label($step, $order['fulfillment'])) ?></h3><time class="muted text-sm"><?= U::e(isset($reached[$step]) ? S::time($reached[$step], 'g:i A') : '—') ?></time></div><p class="muted mt-1"><?= U::e($copy[$step]) ?></p></div></li><?php endforeach; ?></ol></section>
<section class="panel p-5 md:p-6"><?= U::title('Order items','orders','mb-4') ?><?= U::table(['Item', 'Quantity', 'Price', 'Total'], array_map(static fn (array $i): array => [U::productImage('h-12 w-12 inline-block mr-2') . U::e($i['name']), (int) $i['quantity'], S::pesos($i['unit_price_centavos']), S::pesos($i['line_total_centavos'])], $live['items'])) ?><?php if (!$pickup): ?><div class="flex justify-between text-sm mt-4"><span class="muted">Delivery fee<?= $order['distance_display'] !== null ? ' (' . U::e($order['distance_display']) . ' km)' : '' ?></span><span><?= S::pesos($fee) ?></span></div><?php endif; ?><div class="flex justify-between font-bold mt-4"><span>Total</span><span><?= S::pesos($order['total_centavos']) ?></span></div><div class="mt-4 bg-foam rounded-lg p-4"><span class="muted">Payment method</span><p class="font-semibold"><?= $pickup ? 'Cash on pickup' : 'Cash on delivery' ?></p></div></section></div>
<div class="space-y-5"><section class="panel p-5 md:p-6"><?php if ($pickup): ?><?= U::title('Pickup information','file','mb-5') ?><p class="font-bold"><?= U::e($station['name']) ?></p><p><?= U::e($station['address']) ?></p><p class="muted mt-3">Bring empty containers and pay at the station when collecting.</p><?php else: $driver = $live['driver']; ?><?= U::title('Delivery information','truck','mb-5') ?><div class="flex flex-wrap items-center gap-4"><?= U::avatar($driver ? mb_strtoupper(mb_substr($driver['name'], 0, 1)) : '—', 'size-16') ?><div class="flex-1"><h3 class="font-bold text-lg"><?= $driver ? 'Rider ' . U::e($driver['name']) : 'Rider not assigned yet' ?></h3><p class="muted"><?= U::e($station['name']) ?></p><p class="muted"><?= $driver ? U::e($driver['phone']) : 'Shown when your order is out for delivery' ?></p></div><?= $driver ? U::btn('Contact rider', 'tel:' . $driver['phone'], 'secondary', 'phone') : '' ?></div><div class="border-t border-line mt-6 pt-5 flex gap-3"><?= U::icon('pin', 'size-6 text-water') ?><div class="flex-1"><h3 class="font-bold">Delivery address</h3><p class="mt-1"><?= U::e($order['address_label'] ?? '') ?></p><p class="muted"><?= U::e($order['address_text'] ?? '') ?></p><div class="mt-3"><?= U::btn('View address', '/customer/addresses', 'secondary') ?></div></div></div><?php endif; ?></section>
<section class="rounded-xl border border-line bg-foam p-5"><h2 class="font-bold text-lg">Need help?</h2><p class="muted my-3">For questions about your order, contact <?= U::e($station['name']) ?> directly.</p><?= U::btn('View station', '/customer/station?station=' . $station['id'], 'primary', 'store') ?></section>
<?php if ($order['status'] === 'on_hold' && $live['duplicate_of']): ?><section class="rounded-xl border border-amber-200 bg-amber-50 p-5"><h2 class="font-bold text-amber-900">Is this a repeat order?</h2><p class="text-amber-800 mt-2">It matches order <?= U::e($live['duplicate_of']['order_no']) ?> placed <?= U::e(S::time($live['duplicate_of']['created_at'], 'g:i A')) ?>. The station waits for your answer.</p><div class="mt-4 flex flex-wrap gap-2"><?= F::button('/customer/orders/confirm', $fields, 'Yes, I want another', 'primary', 'check', null, '') ?><?= F::button('/customer/orders/cancel', $fields + ['reason' => 'Repeat order declined by customer'], 'Cancel this one', 'secondary', 'close', null, '') ?></div></section>
<?php elseif (!empty($live['can_cancel'])): ?><section class="rounded-xl border border-amber-200 bg-amber-50 p-5"><h2 class="font-bold text-amber-900">Cancel order</h2><p class="text-amber-800 mt-2">You can cancel until the station starts preparing your order.</p><div class="mt-3"><?= F::reason('/customer/orders/cancel', $fields, 'Reason', 'I no longer need it', 'Cancel order', 'secondary', 'Cancel this order?') ?></div></section>
<?php else: ?><section class="rounded-xl border border-amber-200 bg-amber-50 p-5"><h2 class="font-bold text-amber-900">Cancellation unavailable</h2><p class="text-amber-800 mt-2"><?= $order['status'] === 'cancelled' ? 'This order was cancelled' . ($order['cancel_reason'] ? ': ' . U::e($order['cancel_reason']) : '') . '.' : 'This order cannot be cancelled because it is ' . U::e(strtolower(S::label($order['status'], $order['fulfillment']))) . '.' ?></p></section><?php endif ?>
<section class="panel p-5 md:p-6"><?= U::title('Order history','orders','mb-4') ?><?= U::table(['Date & time', 'Status', 'Notes'], array_map(static fn (array $l): array => [U::e(S::time($l['at'], 'M j, Y · g:i A')), U::e(S::label($l['to'], $order['fulfillment'])), U::e($l['reason'] ?? '')], $live['timeline'])) ?></section></div></div>
